import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { mapParams, sanitizeLimit } from "../utils/api-mapping.ts";
import { EnhancedApi } from "../constants/api.ts";
import type {
    IPrivateChatApi,
    ICreateSession,
    IPrivateSession,
    ISendMessage,
    IPrivateMessage,
    IPaginationParams,
    IUnreadCount,
    ISearchMessagesParams,
    ISessionStatistics,
    IChatroomDetail,
    IChatroomFile,
    IVoiceMessageItem,
} from "../models/types.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export class PrivateChatApi extends BaseApi implements IPrivateChatApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    public async createSession(params: ICreateSession): Promise<string> {
        const mappedParams = mapParams(params as unknown as Record<string, unknown>, "privateChat");
        const response = await this.httpClient.post<{
            status: string;
            data?: {
                session_id: string;
                creator_id: string;
                participants: string[];
                session_name: string;
                created_at: string;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_SESSIONS, mappedParams);

        const data = handleApiResponse(response, "Failed to create session");
        return data.session_id || "";
    }

    public async getSessions(userId?: string): Promise<IPrivateSession[]> {
        const mappedParams = mapParams({ userId }, "privateChat");
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                items?: IPrivateSession[];
                total?: number;
                page?: number;
                limit?: number;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_SESSIONS, mappedParams);

        const data = handleApiResponse(response, "Failed to get sessions");
        return data.items || [];
    }

    public async getSessionDetail(sessionId: string): Promise<IPrivateSession | null> {
        try {
            const response = await this.httpClient.get<{
                status: string;
                data?: IPrivateSession;
                error?: string;
            }>(EnhancedApi.PRIVATE_SESSION_DETAIL.replace("{sessionId}", encodeURIComponent(sessionId)));

            return handleApiResponse(response, "Failed to get session detail");
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("not found") || error.message.includes("not exist"))
            ) {
                return null;
            }
            throw error;
        }
    }

    public async closeSession(sessionId: string, userId: string): Promise<boolean> {
        const mappedParams = mapParams({ sessionId, userId }, "privateChat");
        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(EnhancedApi.PRIVATE_SESSION_DELETE.replace("{sessionId}", encodeURIComponent(sessionId)), mappedParams);

        handleApiResponse(response, "Failed to close session");
        return true;
    }

    public async sendMessage(params: ISendMessage): Promise<string> {
        const mappedParams = mapParams(params as unknown as Record<string, unknown>, "privateChat");
        const response = await this.httpClient.post<{
            status: string;
            data?: {
                message_id: string;
                session_id: string;
                sender_id: string;
                content: string;
                message_type: string;
                created_at: string;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_MESSAGES_SEND, mappedParams);

        const data = handleApiResponse(response, "Failed to send message");
        return data.message_id || "";
    }

    public async getMessages(sessionId: string, params?: IPaginationParams): Promise<IPrivateMessage[]> {
        const mappedParams = mapParams(
            {
                session_id: sessionId,
                limit: params?.limit,
                before: params?.before,
                after: params?.after,
            },
            "privateChat",
        );

        if (mappedParams.limit !== undefined) {
            mappedParams.limit = sanitizeLimit(mappedParams.limit as number);
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                items?: IPrivateMessage[];
                total?: number;
                page?: number;
                limit?: number;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_SESSION_MESSAGES.replace("{sessionId}", encodeURIComponent(sessionId)), mappedParams);

        const data = handleApiResponse(response, "Failed to get messages");
        return data.items || [];
    }

    public async markAsRead(messageId: string, userId: string): Promise<boolean> {
        const mappedParams = mapParams({ messageId, userId }, "privateChat");
        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(EnhancedApi.PRIVATE_MESSAGE_READ.replace("{messageId}", encodeURIComponent(messageId)), mappedParams);

        handleApiResponse(response, "Failed to mark as read");
        return true;
    }

    public async getUnreadCount(): Promise<IUnreadCount> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                unread_count?: number;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_UNREAD_COUNT);

        const data = handleApiResponse(response, "Failed to get unread count");
        return {
            total_unread: data.unread_count || 0,
            by_room: [],
        };
    }

    public async searchMessages(params: ISearchMessagesParams): Promise<IPrivateMessage[]> {
        const { userId, query, limit = 50, roomId } = params;

        const queryParams: Record<string, unknown> = { userId, q: query, limit: limit.toString() };
        if (roomId) {
            queryParams.roomId = roomId;
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                items?: IPrivateMessage[];
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_SEARCH, queryParams);

        const data = handleApiResponse(response, "Failed to search messages");
        return data.items || [];
    }

    /**
     * Search private chat sessions by query.
     *
     * @param params - Search parameters.
     * @param params.query - The search query string.
     * @param params.limit - Maximum number of results to return.
     * @param params.userId - Optional user ID to filter by.
     * @returns Promise resolving to an array of matching sessions.
     */
    public async searchSessions(params: {
        query: string;
        limit?: number;
        userId?: string;
    }): Promise<IPrivateSession[]> {
        const { query, limit = 20, userId } = params;

        const queryParams: Record<string, unknown> = {
            q: query,
            limit: limit.toString(),
        };

        if (userId) {
            queryParams.user_id = userId;
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                items?: IPrivateSession[];
                total?: number;
            };
            error?: string;
        }>(`${EnhancedApi.PRIVATE_SESSIONS}/search`, queryParams);

        const data = handleApiResponse(response, "Failed to search sessions");
        return data.items || [];
    }

    public async getSessionStatistics(sessionId: string): Promise<ISessionStatistics> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                message_count?: number;
                participant_count?: number;
                last_activity?: string;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_SESSION_STATS.replace("{sessionId}", encodeURIComponent(sessionId)));

        const data = handleApiResponse(response, "Failed to get session statistics");
        return {
            messageCount: data.message_count ?? 0,
            participantCount: data.participant_count ?? 0,
            lastActivity: data.last_activity,
        };
    }

    public async getChatroomDetail(roomId: string): Promise<IChatroomDetail | null> {
        try {
            const response = await this.httpClient.get<{
                status: string;
                data?: IChatroomDetail;
                error?: string;
            }>(EnhancedApi.PRIVATE_SESSION_DETAIL.replace("{sessionId}", encodeURIComponent(roomId)));

            return handleApiResponse(response, "Failed to get chatroom detail");
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("not found") || error.message.includes("not exist"))
            ) {
                return null;
            }
            throw error;
        }
    }

    public async leaveChatroom(roomId: string): Promise<boolean> {
        const response = await this.httpClient.post<{
            status: string;
            data?: {
                room_id: string;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_ROOM_LEAVE.replace("{roomId}", encodeURIComponent(roomId)), {});

        const data = handleApiResponse(response, "Failed to leave chatroom");
        return data.room_id === roomId;
    }

    public async muteChatroom(roomId: string, mute: boolean): Promise<boolean> {
        const response = await this.httpClient.post<{
            status: string;
            data?: {
                room_id: string;
                mute: boolean;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_ROOM_MUTE.replace("{roomId}", encodeURIComponent(roomId)), { mute });

        const data = handleApiResponse(response, "Failed to mute chatroom");
        return data.mute === mute;
    }

    public async deleteMessage(_roomId: string, messageId: string): Promise<boolean> {
        const response = await this.httpClient.delete<{
            status: string;
            data?: {
                message_id: string;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_MESSAGE_DELETE.replace("{messageId}", encodeURIComponent(messageId)));

        const data = handleApiResponse(response, "Failed to delete message");
        return data.message_id === messageId;
    }

    public async getFiles(roomId: string): Promise<IChatroomFile[]> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                files?: IChatroomFile[];
                total?: number;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_ROOM_FILES.replace("{roomId}", encodeURIComponent(roomId)));

        const data = handleApiResponse(response, "Failed to get files");
        return data.files || [];
    }

    public async getVoiceMessages(roomId: string): Promise<IVoiceMessageItem[]> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                voice_messages?: IVoiceMessageItem[];
                total?: number;
            };
            error?: string;
        }>(EnhancedApi.PRIVATE_ROOM_VOICE.replace("{roomId}", encodeURIComponent(roomId)));

        const data = handleApiResponse(response, "Failed to get voice messages");
        return data.voice_messages || [];
    }
}
